--
-- Name: _prisma_migrations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public._prisma_migrations (
    id character varying(36) NOT NULL,
    checksum character varying(64) NOT NULL,
    finished_at timestamp with time zone,
    migration_name character varying(255) NOT NULL,
    logs text,
    rolled_back_at timestamp with time zone,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    applied_steps_count integer DEFAULT 0 NOT NULL
);


--
-- Name: ai_generations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_generations (
    id uuid NOT NULL,
    user_id integer NOT NULL,
    type public."AiGenerationType" NOT NULL,
    status public."AiGenerationStatus" DEFAULT 'PROCESSING'::public."AiGenerationStatus" NOT NULL,
    model_name character varying(100) NOT NULL,
    request_payload jsonb NOT NULL,
    prompt_messages jsonb NOT NULL,
    response_payload jsonb,
    error_code character varying(100),
    error_message text,
    completed_at timestamp(6) with time zone,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL
);


--
-- Name: ai_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_logs (
    log_id integer NOT NULL,
    model_name character varying(100) NOT NULL,
    action character varying(100) NOT NULL,
    status character varying(20) NOT NULL,
    error_feedback text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ai_logs_status_check CHECK (((status)::text = ANY ((ARRAY['SUCCESS'::character varying, 'ERROR'::character varying])::text[])))
);


