    CONSTRAINT ck_video_recipe_jobs_active_owner CHECK ((((status = ANY (ARRAY['PENDING'::public."VideoRecipeSummaryJobStatus", 'PROCESSING'::public."VideoRecipeSummaryJobStatus"])) AND (active_user_id IS NOT NULL) AND (active_user_id = user_id)) OR ((status = ANY (ARRAY['COMPLETED'::public."VideoRecipeSummaryJobStatus", 'FAILED'::public."VideoRecipeSummaryJobStatus"])) AND (active_user_id IS NULL)))),
    CONSTRAINT ck_video_recipe_jobs_attempt CHECK ((attempt >= 0)),
    CONSTRAINT ck_video_recipe_jobs_lease CHECK ((((status = 'PROCESSING'::public."VideoRecipeSummaryJobStatus") AND (lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR ((status <> 'PROCESSING'::public."VideoRecipeSummaryJobStatus") AND (lease_token IS NULL) AND (lease_expires_at IS NULL))))
);


